  if j==2:p+=R@np.array([0,0,.42])
  if j==4:p+=R@np.array([0,0,.4])
  if j==6:p+=R@np.array([0,0,.126])
 T=np.eye(4);T[:3,:3]=R;T[:3,3]=p;return T

def ik(T,qseed=None):
 if qseed is None:qseed=q[:7].copy()
 def err(x):
  F=fk(x);return np.r_[10*(F[:3,3]-T[:3,3]),Rot.from_matrix(T[:3,:3].T@F[:3,:3]).as_rotvec(),.005*(x-qseed)]
 sol=least_squares(err,qseed,bounds=(np.array(spec['action_types']['joint_position']['lower'][:7]),np.array(spec['action_types']['joint_position']['upper'][:7])),xtol=1e-11,ftol=1e-11,gtol=1e-11)
